// Some portions generated by Codex
import type { Graph } from "./graph-types.ts";
import { isSafeSparqlIri, sparqlFacetValueToken, sparqlResourceToken } from "./rdf-terms.ts";
import { anchoredScoped, EXCLUSION_BUDGET, resourceToken, type GraphScope } from "./rdf-vocabulary.ts";

/** Also sent as the servlet row limit, whose truncation flag keeps a capped answer explicit. */
export const COLLECTION_CONTINUATION_LIMIT = 200;
const RDF = "http://www.w3.org/1999/02/22-rdf-syntax-ns#";
const FIRST = `${RDF}first`, REST = `${RDF}rest`;
const MAX_EXCLUDED_TOKEN = 512;

/** Bounded tuples, streamed from the model. Prefer the current frontier when older cells fill the budget. */
function loadedExclusions(id: string, graph: Graph | undefined, budget: number) {
  if (!graph || budget <= 0) return "";
  const cells = new Set([id]);
  for (const edge of graph.edges) {
    if (edge.predicate === FIRST || edge.predicate === REST) cells.add(edge.source);
    if (edge.predicate === REST) cells.add(edge.target);
  }
  const prefix = "MINUS { VALUES (?source ?predicate ?target) { ";
  const suffix = " } }";
  const rows = new Set<string>();
  let used = prefix.length + suffix.length;
  for (const frontier of [true, false]) {
    for (const edge of graph.edges) {
      if ((edge.source === id) !== frontier || !cells.has(edge.source)) continue;
      const source = sparqlResourceToken(edge.source);
      const predicate = isSafeSparqlIri(edge.predicate) ? `<${edge.predicate}>` : null;
      const target = sparqlFacetValueToken(edge.target);
      if (!source || !predicate || !target || source.length > MAX_EXCLUDED_TOKEN ||
        predicate.length > MAX_EXCLUDED_TOKEN || target.length > MAX_EXCLUDED_TOKEN) continue;
      const row = `(${source} ${predicate} ${target})`;
      if (rows.has(row)) continue;
      if (used + row.length + 1 > budget) return rows.size ? `${prefix}${[...rows].join(" ")}${suffix}` : "";
      rows.add(row);
      used += row.length + 1;
    }
  }
  return rows.size ? `${prefix}${[...rows].join(" ")}${suffix}` : "";
}

/**
 * Prioritize the unresolved cell's first/rest facts so its metadata cannot keep the frontier from advancing.
 * Both branches are limited before their priority sort (at most 402 rows), while the final answer stays at 201.
 * Every other outgoing predicate remains eligible: observed cell metadata must prevent unsafe folding.
 *
 * Loaded facts are excluded within the existing query budget, using only reusable repository identities. Oversize
 * literals, document-local blanks, or facts beyond that budget can still repeat; an answer without new facts must
 * remain explicitly incomplete. These row limits do not bound the server's property-path evaluation; its query
 * timeout still applies. The path and its outgoing facts always share the selected graph scope.
 */
export function collectionContinuationQuery(id: string, scope: GraphScope, loadedGraph?: Graph) {
  const token = resourceToken(id);
  const structural = `<${FIRST}> <${REST}>`;
  const frontier = anchoredScoped([id], "source", `VALUES ?predicate { ${structural} } ?source ?predicate ?target .`, scope);
  const continuation = anchoredScoped([id], "start", `?start <${REST}>* ?source . ?source ?predicate ?target .`, scope);
  const limit = COLLECTION_CONTINUATION_LIMIT + 1;
  const render = (exclusions: string) => `SELECT ?source ?predicate ?target WHERE {
 { { SELECT DISTINCT ?source ?predicate ?target WHERE {
 ${frontier}
 ${exclusions}
 } LIMIT ${limit} } BIND(0 AS ?__collectionPriority) }
 UNION
 { { SELECT DISTINCT ?source ?predicate ?target WHERE {
 ${continuation}
 FILTER(!sameTerm(?source, ${token}) || ?predicate NOT IN (<${FIRST}>, <${REST}>))
 ${exclusions}
 } LIMIT ${limit} } BIND(1 AS ?__collectionPriority) }
}
ORDER BY ?__collectionPriority
LIMIT ${limit}`;
  const empty = render("");
  // The same exclusion block occurs twice. Include fixed query text in the shared budget as well.
  const exclusions = loadedExclusions(id, loadedGraph, Math.floor((EXCLUSION_BUDGET - empty.length) / 2));
  return exclusions ? render(exclusions) : empty;
}
